def generate(rng, n):
    if n < 1:
        n = 1
    chars = [rng.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(n)]
    s = "".join(chars)
    if rng.random() < 0.5:
        t_list = list(s)
        rng.shuffle(t_list)
        t = "".join(t_list)
    else:
        t = "".join(rng.choice("abcdefghijklmnopqrstuvwxyz") for _ in range(n))
    return [s, t]

